  // ============ Constants ============
  public static final long DEFAULT_EVENT_RETENTION_HOURS = 168L;
  public static final long DEFAULT_MAX_GRAPH_NODES = 5000L;
  public static final long DEFAULT_STALE_ENTITY_SECONDS = 300L;
  public static final long DEFAULT_MAX_TOOL_CALL_PAYLOAD_BYTES = 65536L;
  public static final long DEFAULT_USER_COUNT = 10L;
  public static final long DEFAULT_AGENTS_PER_USER = 4L;
  public static final long DEFAULT_MCP_SERVER_COUNT = 5L;
