  public static String observedTokenToJson(Aegis.ObservedToken msg) throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "ObservedToken is null");
    }
    try {
      Gson gson = new Gson();
      JsonObject obj = new JsonObject();
      if (msg.getObservedAtMs() != 0) {
        obj.addProperty("observed_at_ms", msg.getObservedAtMs());
      }
      if (!msg.getObserverService().isEmpty()) {
        obj.addProperty("observer_service", msg.getObserverService());
      }
      if (!msg.getObserverHostId().isEmpty()) {
        obj.addProperty("observer_host_id", msg.getObserverHostId());
      }
      if (!msg.getTraceId().isEmpty()) {
        obj.addProperty("trace_id", msg.getTraceId());
      }
      if (!msg.getSpanId().isEmpty()) {
        obj.addProperty("span_id", msg.getSpanId());
      }
      if (!msg.getParentSpanId().isEmpty()) {
        obj.addProperty("parent_span_id", msg.getParentSpanId());
      }
      if (!msg.getSubject().isEmpty()) {
        obj.addProperty("subject", msg.getSubject());
      }
      if (!msg.getIssuer().isEmpty()) {
        obj.addProperty("issuer", msg.getIssuer());
      }
      if (!msg.getAudience().isEmpty()) {
        obj.addProperty("audience", msg.getAudience());
      }
      if (msg.getIssuedAt() != 0) {
        obj.addProperty("issued_at", msg.getIssuedAt());
      }
      if (msg.getExpiresAt() != 0) {
        obj.addProperty("expires_at", msg.getExpiresAt());
      }
      if (!msg.getTokenId().isEmpty()) {
        obj.addProperty("token_id", msg.getTokenId());
      }
      if (!msg.getSubjectType().isEmpty()) {
        obj.addProperty("subject_type", msg.getSubjectType());
      }
      if (msg.getEntitlementsCount() > 0) {
        JsonArray arr = new JsonArray();
        for (int i = 0; i < msg.getEntitlementsCount(); i++) {
          arr.add(msg.getEntitlements(i));
        }
        obj.add("entitlements", arr);
      }
      if (msg.getDelegationChainCount() > 0) {
        JsonArray arr = new JsonArray();
        for (int i = 0; i < msg.getDelegationChainCount(); i++) {
          arr.add(msg.getDelegationChain(i));
        }
        obj.add("delegation_chain", arr);
      }
      if (!msg.getClientComponent().isEmpty()) {
        obj.addProperty("client_component", msg.getClientComponent());
      }
      if (msg.getProfilesCount() > 0) {
        JsonArray arr = new JsonArray();
        for (int i = 0; i < msg.getProfilesCount(); i++) {
          arr.add(msg.getProfiles(i));
        }
        obj.add("profiles", arr);
      }
      if (!msg.getAuthorizedParty().isEmpty()) {
        obj.addProperty("authorized_party", msg.getAuthorizedParty());
      }
      if (!msg.getAuthType().isEmpty()) {
        obj.addProperty("auth_type", msg.getAuthType());
      }
      if (msg.hasExtraClaims()) {
        try {
          obj.add(
              "extra_claims",
              gson.fromJson(JsonFormat.printer().print(msg.getExtraClaims()), JsonElement.class));
        } catch (Exception e) {
        }
      }
      if (msg.getLabelsCount() > 0) {
        JsonObject mapObj = new JsonObject();
        for (var entry : msg.getLabelsMap().entrySet()) {
          mapObj.addProperty(entry.getKey(), entry.getValue());
        }
        obj.add("labels", mapObj);
      }
      if (!msg.getObservedMethod().isEmpty()) {
        obj.addProperty("observed_method", msg.getObservedMethod());
      }
      if (msg.getResultValue() != 0) {
        obj.addProperty("result", observationResultToString(msg.getResult()));
      }
      if (!msg.getRejectionReason().isEmpty()) {
        obj.addProperty("rejection_reason", msg.getRejectionReason());
      }
      if (msg.hasProvenance()) {
        try {
          obj.add(
              "provenance",
              gson.fromJson(eventProvenanceToJson(msg.getProvenance()), JsonElement.class));
        } catch (Exception e) {
        }
      }
      if (msg.getSchemaVersion() != 0) {
        obj.addProperty("schema_version", msg.getSchemaVersion());
      }
      if (!msg.getTokenFormatVersion().isEmpty()) {
        obj.addProperty("token_format_version", msg.getTokenFormatVersion());
      }
      return gson.toJson(obj);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to serialize ObservedToken to JSON: " + e.getMessage(),
          e);
    }
  }

