  // ============ Validation ============
  public static void validateConfig(Aegis.Config msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate eventRetentionHours (assert_ge: 1)
    if (msg.getEventRetentionHours() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field eventRetentionHours must be >= 1, got: %s", msg.getEventRetentionHours()));
    }
    // Validate maxGraphNodes (assert_ge: 100)
    if (msg.getMaxGraphNodes() < 100) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field maxGraphNodes must be >= 100, got: %s", msg.getMaxGraphNodes()));
    }
    // Validate staleEntitySeconds (assert_ge: 30)
    if (msg.getStaleEntitySeconds() < 30) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field staleEntitySeconds must be >= 30, got: %s", msg.getStaleEntitySeconds()));
    }
    // Validate maxToolCallPayloadBytes (assert_ge: 1024)
    if (msg.getMaxToolCallPayloadBytes() < 1024) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field maxToolCallPayloadBytes must be >= 1024, got: %s",
              msg.getMaxToolCallPayloadBytes()));
    }
  }

  public static void validateSimulationProfile(Aegis.SimulationProfile msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate hostId (assert_required)
    if (msg.getHostId().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field hostId is required");
    }
    // Validate userCount (assert_ge: 1)
    if (msg.getUserCount() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field userCount must be >= 1, got: %s", msg.getUserCount()));
    }
    // Validate userCount (assert_le: 100)
    if (msg.getUserCount() > 100) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field userCount must be <= 100, got: %s", msg.getUserCount()));
    }
    // Validate agentsPerUser (assert_ge: 1)
    if (msg.getAgentsPerUser() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field agentsPerUser must be >= 1, got: %s", msg.getAgentsPerUser()));
    }
    // Validate agentsPerUser (assert_le: 20)
    if (msg.getAgentsPerUser() > 20) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field agentsPerUser must be <= 20, got: %s", msg.getAgentsPerUser()));
    }
    // Validate mcpServerCount (assert_ge: 1)
    if (msg.getMcpServerCount() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field mcpServerCount must be >= 1, got: %s", msg.getMcpServerCount()));
    }
    // Validate mcpServerCount (assert_le: 50)
    if (msg.getMcpServerCount() > 50) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field mcpServerCount must be <= 50, got: %s", msg.getMcpServerCount()));
    }
    // Validate batchIntervalMs (assert_ge: 100)
    if (msg.getBatchIntervalMs() < 100) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field batchIntervalMs must be >= 100, got: %s", msg.getBatchIntervalMs()));
    }
  }

