  /** Applies default values to zero-valued fields of Config. */
  public static Aegis.Config.Builder configDefaults(Aegis.Config msg) {
    if (msg == null) {
      return null;
    }
    Aegis.Config.Builder builder = msg.toBuilder();
    if (msg.getEventRetentionHours() == 0) {
      builder.setEventRetentionHours((int) Helpers.DEFAULT_EVENT_RETENTION_HOURS);
    }
    if (msg.getMaxGraphNodes() == 0) {
      builder.setMaxGraphNodes((int) Helpers.DEFAULT_MAX_GRAPH_NODES);
    }
    if (msg.getStaleEntitySeconds() == 0) {
      builder.setStaleEntitySeconds((int) Helpers.DEFAULT_STALE_ENTITY_SECONDS);
    }
    if (msg.getMaxToolCallPayloadBytes() == 0) {
      builder.setMaxToolCallPayloadBytes((int) Helpers.DEFAULT_MAX_TOOL_CALL_PAYLOAD_BYTES);
    }
    return builder;
  }

