  public static Aegis.TraceSpan.Builder mergeTraceSpan(Aegis.TraceSpan dst, Aegis.TraceSpan src) {
    Aegis.TraceSpan.Builder builder = dst.toBuilder();
    if (dst.getSpanId().isEmpty()) {
      builder.setSpanId(src.getSpanId());
    }
    if (dst.getParentSpanId().isEmpty()) {
      builder.setParentSpanId(src.getParentSpanId());
    }
    if (dst.getSpanType().isEmpty()) {
      builder.setSpanType(src.getSpanType());
    }
    if (dst.getStartedMs() == 0) {
      builder.setStartedMs(src.getStartedMs());
    }
    if (dst.getEndedMs() == 0) {
      builder.setEndedMs(src.getEndedMs());
    }
    if (dst.getServiceId().isEmpty()) {
      builder.setServiceId(src.getServiceId());
    }
    if (dst.getAgentId().isEmpty()) {
      builder.setAgentId(src.getAgentId());
    }
    if (!dst.hasToken() && src.hasToken()) {
      builder.setToken(src.getToken());
    } else if (dst.hasToken() && src.hasToken()) {
      builder.setToken(mergeObservedToken(dst.getToken(), src.getToken()).build());
    }
    if (!dst.hasConversationEvent() && src.hasConversationEvent()) {
      builder.setConversationEvent(src.getConversationEvent());
    } else if (dst.hasConversationEvent() && src.hasConversationEvent()) {
      builder.setConversationEvent(
          mergeMcpConversationEvent(dst.getConversationEvent(), src.getConversationEvent())
              .build());
    }
    if (!dst.hasAction() && src.hasAction()) {
      builder.setAction(src.getAction());
    } else if (dst.hasAction() && src.hasAction()) {
      builder.setAction(mergeActionEvent(dst.getAction(), src.getAction()).build());
    }
    return builder;
  }

