  public static Map<String, String> observedTokenToEnvVar(Aegis.ObservedToken msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_OBSERVED_TOKEN_OBSERVED_AT_MS", String.valueOf(msg.getObservedAtMs()));
    result.put("PROTO_OBSERVED_TOKEN_OBSERVER_SERVICE", msg.getObserverService());
    result.put("PROTO_OBSERVED_TOKEN_OBSERVER_HOST_ID", msg.getObserverHostId());
    result.put("PROTO_OBSERVED_TOKEN_TRACE_ID", msg.getTraceId());
    result.put("PROTO_OBSERVED_TOKEN_SPAN_ID", msg.getSpanId());
    result.put("PROTO_OBSERVED_TOKEN_PARENT_SPAN_ID", msg.getParentSpanId());
    result.put("PROTO_OBSERVED_TOKEN_SUBJECT", msg.getSubject());
    result.put("PROTO_OBSERVED_TOKEN_ISSUER", msg.getIssuer());
    result.put("PROTO_OBSERVED_TOKEN_AUDIENCE", msg.getAudience());
    result.put("PROTO_OBSERVED_TOKEN_ISSUED_AT", String.valueOf(msg.getIssuedAt()));
    result.put("PROTO_OBSERVED_TOKEN_EXPIRES_AT", String.valueOf(msg.getExpiresAt()));
    result.put("PROTO_OBSERVED_TOKEN_TOKEN_ID", msg.getTokenId());
    result.put("PROTO_OBSERVED_TOKEN_SUBJECT_TYPE", msg.getSubjectType());
    if (!msg.getEntitlementsList().isEmpty()) {
      result.put("PROTO_OBSERVED_TOKEN_ENTITLEMENTS", String.join(",", msg.getEntitlementsList()));
    }
    if (!msg.getDelegationChainList().isEmpty()) {
      result.put(
          "PROTO_OBSERVED_TOKEN_DELEGATION_CHAIN", String.join(",", msg.getDelegationChainList()));
    }
    result.put("PROTO_OBSERVED_TOKEN_CLIENT_COMPONENT", msg.getClientComponent());
    if (!msg.getProfilesList().isEmpty()) {
      result.put("PROTO_OBSERVED_TOKEN_PROFILES", String.join(",", msg.getProfilesList()));
    }
    result.put("PROTO_OBSERVED_TOKEN_AUTHORIZED_PARTY", msg.getAuthorizedParty());
    result.put("PROTO_OBSERVED_TOKEN_AUTH_TYPE", msg.getAuthType());
    result.put("PROTO_OBSERVED_TOKEN_OBSERVED_METHOD", msg.getObservedMethod());
    result.put("PROTO_OBSERVED_TOKEN_RESULT", observationResultToString(msg.getResult()));
    result.put("PROTO_OBSERVED_TOKEN_REJECTION_REASON", msg.getRejectionReason());
    if (msg.hasProvenance()) {
      result.putAll(eventProvenanceToEnvVar(msg.getProvenance()));
    }
    result.put("PROTO_OBSERVED_TOKEN_SCHEMA_VERSION", String.valueOf(msg.getSchemaVersion()));
    result.put("PROTO_OBSERVED_TOKEN_TOKEN_FORMAT_VERSION", msg.getTokenFormatVersion());
    return result;
  }

